import { InsufficientStockError, InvalidTransitionError, InvalidValueError } from '../domain/DomainErrors';
import { ConflictError, NotFoundError, ValidationError } from './ApplicationErrors';

export type ErrorKind = 'invalid' | 'not-found' | 'conflict' | 'unexpected';

export interface ClassifiedError {
  kind: ErrorKind;
  message: string;
}

/**
 * Translates application and domain failures into transport-neutral categories,
 * so adapters never need to know the individual error types.
 */
export function classifyError(error: unknown): ClassifiedError {
  if (error instanceof ValidationError || error instanceof InvalidValueError) {
    return { kind: 'invalid', message: error.message };
  }
  if (error instanceof NotFoundError) {
    return { kind: 'not-found', message: error.message };
  }
  if (
    error instanceof ConflictError ||
    error instanceof InsufficientStockError ||
    error instanceof InvalidTransitionError
  ) {
    return { kind: 'conflict', message: error.message };
  }
  return { kind: 'unexpected', message: 'Internal server error' };
}

