import { OrderRepository } from '../domain/OrderRepository';
import { isOrderStatus } from '../domain/OrderStatus';
import { ValidationError } from './ApplicationErrors';
import { OrderDto, toOrderDto } from './OrderDto';

/** Staff view: every order currently in the given state, oldest first. */
export class ListOrdersByStateUseCase {
  constructor(private readonly orders: OrderRepository) {}

  execute(state: string): OrderDto[] {
    if (!isOrderStatus(state)) {
      throw new ValidationError(`Unknown order state '${state}'`);
    }
    return this.orders
      .findByStatus(state)
      .sort((a, b) => a.placedAt.getTime() - b.placedAt.getTime())
      .map(toOrderDto);
  }
}

