import { ProductRepository } from '../domain/ProductRepository';
import { ProductStockDto, toProductStockDto } from './ProductStockDto';

/** Staff view: the stock level of every catalogue product. */
export class ListProductStockUseCase {
  constructor(private readonly products: ProductRepository) {}

  execute(): ProductStockDto[] {
    return this.products
