import { Order } from '../domain/Order';
import { OrderLine } from '../domain/OrderLine';
import { OrderRepository } from '../domain/OrderRepository';
import { ProductRepository } from '../domain/ProductRepository';
import { StockAllocationService } from '../domain/StockAllocationService';
import { Clock } from './Clock';
import { EntityLookupService } from './EntityLookupService';
import { IdGenerator } from './IdGenerator';
import { OrderDto, PlaceOrderCommand, toOrderDto } from './OrderDto';

/** Places an order and reserves its stock; nothing is stored if any line cannot be reserved. */
export class PlaceOrderUseCase {
  private readonly allocation = new StockAllocationService();

  constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
    private readonly lookup: EntityLookupService,
    private readonly ids: IdGenerator,
    private readonly clock: Clock,
  ) {}

  execute(command: PlaceOrderCommand): OrderDto {
    const lines = command.lines.map((line) => OrderLine.of(line.productId, line.quantity));
    const order = Order.place(this.ids.nextId(), command.customerId, lines, this.clock.now());

    const products = this.lookup.requireProductsFor(order.lines);
    this.allocation.reserve(order.lines, products);

    products.forEach((product) => this.products.save(product));
    this.orders.save(order);
    return toOrderDto(order);
  }
}

