import { Product } from '../domain/Product';
import { ProductRepository } from '../domain/ProductRepository';
import { ConflictError } from './ApplicationErrors';
import { ProductStockDto, RegisterProductCommand, toProductStockDto } from './ProductStockDto';

/** Adds a product to the catalogue with its initial stock. */
export class RegisterProductUseCase {
  constructor(private readonly products: ProductRepository) {}

  execute(command: RegisterProductCommand): ProductStockDto {
    if (this.products.findById(command.productId) !== undefined) {
      throw new ConflictError(`Product ${command.productId} already exists`);
    }
    const product = Product.create(command.productId, command.name, command.initialStock);
    this.products.save(product);
    return toProductStockDto(product);
  }
}

